import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

// Books live in memory and the whole list is rewritten to a JSON file on
// every change. Writes go to a temp file first and are then renamed over the
// real one, so a crash mid-write can't leave a half-written file behind.
export async function openStore(file) {
  let books = [];
  try {
    books = JSON.parse(await readFile(file, 'utf8'));
  } catch (err) {
    // A missing file just means no books yet. Anything else (e.g. invalid
    // JSON) is surfaced rather than silently replaced with an empty list.
    if (err.code !== 'ENOENT') {
      throw new Error(`Could not read books from ${file}: ${err.message}`);
    }
  }

  // Chain writes so two quick changes can't race each other to disk.
  let pending = Promise.resolve();
  function save() {
    const snapshot = JSON.stringify(books, null, 2) + '\n';
    pending = pending.then(async () => {
      await mkdir(dirname(file), { recursive: true });
      const tmp = `${file}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, file);
    });
    return pending;
  }

  return {
    list() {
      return [...books];
    },

    get(id) {
      return books.find((b) => b.id === id);
    },

    async add({ title, author, notes }) {
      const book = {
        id: randomUUID(),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },

    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return undefined;
      if (book.status !== 'finished') {
        book.status = 'finished';
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

