const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escape(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => ESCAPES[c]);
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #2a5db0; }
  h1 a { color: inherit; text-decoration: none; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .author, .meta, .empty { color: #666; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 1rem; border-radius: 4px; }
  form.add { display: grid; gap: .75rem; margin-top: 1rem; }
  form.add label { display: grid; gap: .25rem; font-weight: 600; }
  input, textarea, button { font: inherit; padding: .4rem .6rem; }
  textarea { min-height: 6rem; }
  form.inline { margin: 0; }
  .error { color: #b00020; }
  .share input { width: 100%; box-sizing: border-box; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finishButton =
    book.status === 'reading'
      ? `<form class="inline" method="post" action="/books/${escape(book.id)}/finish">
          <button type="submit">Mark finished</button>
        </form>`
      : `<span class="meta">${formatDate(book.finishedAt)}</span>`;
  return `<li>
      <span><a href="/books/${escape(book.id)}">${escape(book.title)}</a>${
        book.author ? ` <span class="author">by ${escape(book.author)}</span>` : ''
      }</span>
      ${finishButton}
    </li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${emptyText}</p>`;
  return `<ul class="books">${books.map(bookItem).join('')}</ul>`;
}

export function homePage(books, { error, values = {} } = {}) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  return layout(
    'My books',
    `<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.')}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}

<h2>Add a book</h2>
${error ? `<p class="error">${escape(error)}</p>` : ''}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required maxlength="300" value="${escape(values.title)}"></label>
  <label>Author <input name="author" maxlength="300" value="${escape(values.author)}"></label>
  <label>Notes <textarea name="notes" maxlength="20000">${escape(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book, url) {
  const status =
    book.status === 'finished'
      ? `Finished ${formatDate(book.finishedAt)}`
      : `Reading since ${formatDate(book.addedAt)}`;

  return layout(
    book.title,
    `<h2>${escape(book.title)}</h2>
${book.author ? `<p class="author">by ${escape(book.author)}</p>` : ''}
<p class="meta">${status}</p>

<h3>Notes</h3>
${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : '<p class="empty">No notes.</p>'}

${
  book.status === 'reading'
    ? `<form method="post" action="/books/${escape(book.id)}/finish">
  <button type="submit">Mark finished</button>
</form>`
    : ''
}

<p class="share"><label>Link to this book<br>
  <input readonly value="${escape(url)}" onfocus="this.select()"></label></p>

<p><a href="/">&larr; All books</a></p>`,
  );
}

export function notFoundPage() {
  return layout('Not found', `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`);
}

