import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { openStore } from '../src/store.js';

let dir, file, server, base;

async function start() {
  const store = await openStore(file);
  server = createApp(store);
  await new Promise((r) => server.listen(0, r));
  base = `http://localhost:${server.address().port}`;
  return store;
}

async function stop() {
  await new Promise((r) => server.close(r));
}

function post(path, fields) {
  return fetch(base + path, {
    method: 'POST',
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'books.json');
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('books app', () => {
  it('shows empty lists on first run', async () => {
    await start();
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
  });

  it('adds a book and lists it under currently reading', async () => {
    const store = await start();
    const res = await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const [book] = store.list();
    const html = await (await fetch(base + '/')).text();
    const reading = html.split('<h2>Finished</h2>')[0];
    expect(reading).toContain(`href="/books/${book.id}"`);
    expect(reading).toContain('Dune');
    expect(reading).toContain('by Frank Herbert');
  });

  it('rejects a book with no title and keeps the entered values', async () => {
    const store = await start();
    const res = await post('/books', { title: '   ', author: 'Someone', notes: 'kept' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('A title is required.');
    expect(html).toContain('value="Someone"');
    expect(html).toContain('>kept</textarea>');
    expect(store.list()).toHaveLength(0);
  });

  it('shows a book page with title, author, notes and a shareable link', async () => {
    const store = await start();
    await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Line one\nLine two' });
    const [book] = store.list();

    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('<h2>Dune</h2>');
    expect(html).toContain('by Frank Herbert');
    expect(html).toContain('Line one\nLine two');
    expect(html).toContain(`value="${base}/books/${book.id}"`);
  });

  it('marks a book as finished', async () => {
    const store = await start();
    await post('/books', { title: 'Dune' });
    const [book] = store.list();

    const res = await post(`/books/${book.id}/finish`, {});
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');
    expect(store.get(book.id).status).toBe('finished');

    const html = await (await fetch(base + '/')).text();
    const [reading, finished] = html.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Dune');
